import { router } from 'expo-router';
import Head from 'expo-router/head';
import { Image, Pressable, StyleSheet, View } from 'react-native';

import { useStrings } from '@/i18n';
import { useOnboardingStore } from '@/state/onboarding-store';
import { AppText } from '@/ui/components/AppText';
import { PillButton } from '@/ui/components/PillButton';
import { Screen } from '@/ui/components/Screen';
import { radius, spacing, useTheme } from '@/ui/theme';

/** The app icon, generated by `npm run icons`; at night, with the dark board iOS also uses. */
const ICONS = {
  light: require('../../assets/images/welcome-icon.png'),
  dark: require('../../assets/images/welcome-icon-dark.png'),
} as const;

/** Icon size (pt), with the corners of a home screen icon. */
const ICON_SIZE = 160;

/**
 * The first screen after installing the app (the home screen opens it, see
 * `useTutorialDue`): the icon and the name, "Learn to play" for the tutorial, and
 * "I already know how to play" for anyone who wants to go straight in.
 */
export default function WelcomeScreen() {
  const t = useStrings();
  const { palette, scheme } = useTheme();
  const markTutorialSeen = useOnboardingStore((s) => s.markTutorialSeen);

  const skip = () => {
    markTutorialSeen();
    if (router.canGoBack()) router.back();
    else router.replace('/');
  };

  return (
    <Screen>
      <Head>
        <title>{t.appName}</title>
      </Head>
      <View style={styles.hero}>
        <Image
          source={ICONS[scheme]}
          style={[styles.icon, { borderColor: palette.tileBorder }]}
          accessible={false}
          aria-hidden
        />
        <AppText variant="title" accessibilityRole="header" maxFontSizeMultiplier={1.3}>
          {t.appName}
        </AppText>
        <AppText tone="secondary" style={styles.tagline}>
          {t.welcome.tagline}
        </AppText>
      </View>
      <View style={styles.actions}>
        <PillButton label={t.welcome.learn} onPress={() => router.replace('/learn')} />
        <Pressable
          onPress={skip}
          accessibilityRole="button"
          hitSlop={6}
          style={({ pressed }) => [styles.known, pressed && { backgroundColor: palette.surfacePressed }]}>
          <AppText variant="label" tone="secondary" maxFontSizeMultiplier={1.4}>
            {t.welcome.known}
          </AppText>
        </Pressable>
      </View>
    </Screen>
  );
}

const styles = StyleSheet.create({
  hero: { flex: 1, alignItems: 'center', justifyContent: 'center', gap: spacing.md },
  icon: {
    width: ICON_SIZE,
    height: ICON_SIZE,
    // The rounding of an app icon on iOS (about 22 % of its side).
    borderRadius: Math.round(ICON_SIZE * 0.2237),
    borderWidth: StyleSheet.hairlineWidth,
    marginBottom: spacing.md,
  },
  tagline: { textAlign: 'center' },
  actions: { alignItems: 'center', gap: spacing.sm, paddingBottom: spacing.xl },
  known: {
    minHeight: 44,
    paddingHorizontal: spacing.lg,
    borderRadius: radius.pill,
    alignItems: 'center',
    justifyContent: 'center',
  },
});
